cd /home/ctfplayer/ctf_files && cat > examine_functions.py << 'EOF'
from pwn import *

# Load the binary
binary = ELF('./bard')

# Print all the functions we can find
print("Functions:")
for func in binary.functions:
    print(f"  {func}: {hex(binary.functions[func].address)}")

# Print all the symbols
print("\nSymbols:")
for sym in binary.symbols:
    if 'got' in sym or 'plt' in sym:
        print(f"  {sym}: {hex(binary.symbols[sym])}")

# Look for interesting strings
print("\nInteresting Strings:")
for section in binary.sections:
    if section.name == '.rodata':
        data = binary.read(section.header.sh_addr, section.header.sh_size)
        for string in data.split(b'\x00'):
            if len(string) > 5:
                print(f"  {string}")
EOF

python3 examine_functions.py
